{
  "decisions": [
    {
      "surface": "outflows",
      "action": "create",
      "measure": "outflows",
      "description": "Represents the total value of capital or assets leaving a specific segment or market."
    },
    {
      "surface": "gross fiscal deficit (gfd)",
      "action": "create",
      "measure": "gross fiscal deficit",
      "description": "The excess of total government expenditure over total revenue receipts and non-debt capital receipts, expressed as a ratio of GDP."
    },
    {
      "surface": "amount below be",
      "action": "create",
      "measure": "amount below budget estimate",
      "description": "The difference between actual expenditure and the budgeted estimate when the actual is lower."
    },
    {
      "surface": "budgeted decline",
      "action": "create",
      "measure": "budgeted decline",
      "description": "The projected reduction in a specific expenditure or revenue item in the budget."
    },
    {
      "surface": "expected increase",
      "action": "create",
      "measure": "expected increase",
      "description": "The projected rise in a specific expenditure or revenue item."
    },
    {
      "surface": "budgeted fall as per cent of gdp",
      "action": "create",
      "measure": "budgeted fall as percentage of gdp",
      "description": "The projected decrease in a budget item expressed as a percentage of GDP."
    },
    {
      "surface": "expected per cent of gdp",
      "action": "create",
      "measure": "expected percentage of gdp",
      "description": "A projected value expressed as a percentage of GDP."
    },
    {
      "surface": "budgeted growth",
      "action": "create",
      "measure": "budgeted growth rate",
      "description": "The projected percentage increase of a financial metric in the budget."
    },
    {
      "surface": "estimated per cent of gdp",
      "action": "create",
      "measure": "estimated percentage of gdp",
      "description": "An estimated value expressed as a percentage of GDP."
    },
    {
      "surface": "budgeted per cent of gdp",
      "action": "create",
      "measure": "budgeted percentage of gdp",
      "description": "A budgeted value expressed as a percentage of GDP."
    },
    {
      "surface": "budgeted gfd as per cent of gdp",
      "action": "link",
      "measure": "gross fiscal deficit",
      "description": "Links to the canonical gross fiscal deficit measure."
    },
    {
      "surface": "per cent of budget estimates",
      "action": "create",
      "measure": "percentage of budget estimates",
      "description": "The ratio of an actual value to its corresponding budget estimate."
    },
    {
      "surface": "budgeted per cent",
      "action": "create",
      "measure": "budgeted percentage",
      "description": "A generic budgeted percentage value."
    },
    {
      "surface": "budgeted percentage increase from 2024-25 (re)",
      "action": "create",
      "measure": "budgeted percentage increase",
      "description": "The projected percentage growth of a metric relative to the revised estimates of the previous period."
    },
    {
      "surface": "total outlay",
      "action": "create",
      "measure": "total outlay",
      "description": "The total amount of funds allocated for a specific scheme or project."
    },
    {
      "surface": "percentage increase over 2024-25 (re) levels",
      "action": "create",
      "measure": "percentage increase over previous period",
      "description": "The percentage growth of a metric compared to the revised estimates of the prior period."
    },
    {
      "surface": "per cent",
      "action": "create",
      "measure": "percentage",
      "description": "A generic percentage value."
    },
    {
      "surface": "net portfolio inflows",
      "action": "create",
      "measure": "net portfolio inflows",
      "description": "The net value of foreign portfolio investments entering a market."
    },
    {
      "surface": "share of total merchandise exports",
      "action": "create",
      "measure": "share of total merchandise exports",
      "description": "The proportion of a specific category within total merchandise exports."
    },
    {
      "surface": "share of electronic goods exports",
      "action": "create",
      "measure": "share of electronic goods exports",
      "description": "The proportion of a specific category within total electronic goods exports."
    },
    {
      "surface": "share of total merchandise imports",
      "action": "create",
      "measure": "share of total merchandise imports",
      "description": "The proportion of a specific category within total merchandise imports."
    },
    {
      "surface": "trade surplus",
      "action": "create",
      "measure": "trade surplus",
      "description": "The amount by which the value of exports exceeds the value of imports for a specific category."
    },
    {
      "surface": "share of total trade deficit",
      "action": "create",
      "measure": "share of total trade deficit",
      "description": "The proportion of a specific category's deficit within the total trade deficit."
    },
    {
      "surface": "growth rate (y-o-y)",
      "action": "create",
      "measure": "year on year growth rate",
      "description": "The percentage change of a metric compared to the same period in the previous year."
    }
  ]
}
